<script lang="ts">
 import { api, type Grant } from './api'; import {canEdit} from './findings'; import {dataUrl,nextSort,expiryError} from './data-pages'; import Table from './components/Table.svelte'; import Pagination from './components/Pagination.svelte'; import Skeleton from './components/Skeleton.svelte'; import RetryState from './components/RetryState.svelte'; import EmptyState from './components/EmptyState.svelte';
 let {realms,grants}:{realms:string[],grants:Grant[]}=$props();
 type Oath={id:number,advisory_id:string,name_key:string,service_name:string,realm:string|null,kind:string,reason:string,status:string,expires_at:string|null,review_at:string|null};
 let rows=$state<Oath[]>([]),tab=$state('active'),offset=$state(0),sort=$state('date'),order=$state('asc'),loading=$state(true),failed=$state(false),revision=$state(0), action=$state<'extend'|'revoke'|null>(null), target=$state<Oath|null>(null),until=$state(''),error=$state(''),busy=$state(false);
 let url=$derived(dataUrl('/api/v1/ui/oaths',realms,offset,sort,order,{tab}));
 $effect(()=>{realms.join(',');offset=0;target=null;action=null;});
 $effect(()=>{const targetUrl=url;revision;let active=true;loading=true;failed=false;api<Oath[]>(targetUrl).then(data=>{if(active){rows=data;loading=false;}}).catch(()=>{if(active){failed=true;loading=false;}});return ()=>{active=false};});
 function chooseTab(value:string){tab=value;offset=0;target=null;action=null;}
 function changeSort(field:string){[sort,order]=nextSort(sort,order,field);offset=0;} function sortState(field:string):'ascending'|'descending'|'none'{return sort===field?(order==='asc'?'ascending':'descending'):'none';}
 function start(row:Oath, operation:'extend'|'revoke'){target=row;action=operation;until='';error='';}
 async function confirm(){if(!target||!action)return;if(action==='extend' && (error=expiryError(until)))return;busy=true;error='';try{await api(`/api/v1/oaths/${target.id}/${action}`,{method:'POST',...(action==='extend'?{headers:{'Content-Type':'application/json'},body:JSON.stringify({until})}:{})});target=null;action=null;revision++;}catch{error='Could not update this oath. Please try again.';}finally{busy=false;}}
</script>
<div class="page"><div class="tabs" aria-label="Oath status">{#each [['active','Active'],['expiring','Expiring within 7 days'],['past','Expired / revoked']] as [id,label]}<button aria-pressed={tab===id} onclick={()=>chooseTab(id)}>{label}</button>{/each}</div>
{#if loading}<Skeleton/>{:else if failed}<RetryState retry={()=>revision++}/>{:else if !rows.length}<EmptyState message="No oaths in this view."/>{:else}<Table label="Oaths"><thead><tr>{#each [['advisory','Advisory'],['service','Service'],['realm','Realm'],['kind','Decision'],['date','Expiry / review'],['status','Status']] as [field,label]}<th aria-sort={sortState(field)}><button onclick={()=>changeSort(field)}>{label} ↕</button></th>{/each}<th>Reason</th><th>Actions</th></tr></thead><tbody>{#each rows as row}<tr><td class="mono">{row.advisory_id}<br/>{row.name_key}</td><td>{row.service_name}</td><td>{row.realm ?? 'All realms'}</td><td>{row.kind}</td><td>{(row.expires_at ?? row.review_at)?.slice(0,10) ?? '—'}</td><td>{row.status==='active' && (row.expires_at ?? row.review_at) && new Date((row.expires_at ?? row.review_at)!).getTime()<=Date.now() ? 'expired' : row.status}</td><td>{row.reason}</td><td>{#if canEdit(grants,row.realm ?? '*') && row.status!=='revoked'}<div class="actions"><button onclick={()=>start(row,'extend')}>Extend</button><button onclick={()=>start(row,'revoke')}>Revoke</button></div>{:else}—{/if}</td></tr>{/each}</tbody></Table>{/if}
{#if !failed}<Pagination {offset} count={rows.length} {loading} change={(n)=>offset=n}/>{/if}
{#if target && action}<section class="confirm" aria-labelledby="confirm-title"><h2 id="confirm-title">{action==='extend'?'Extend':'Revoke'} oath for <span class="mono">{target.advisory_id}</span>?</h2><p>{target.service_name} · {target.realm ?? 'All realms'}</p>{#if action==='extend'}<label>New expiry / review date <input type="date" bind:value={until}/></label>{:else}<p>This removes the oath's protection for this finding.</p>{/if}{#if error}<p role="alert">{error}</p>{/if}<div class="actions"><button disabled={busy} onclick={confirm}>Confirm {action}</button><button disabled={busy} onclick={()=>{target=null;action=null;}}>Cancel</button></div></section>{/if}</div>
<style>.page{margin-top:2rem}.tabs,.actions{display:flex;gap:.5rem;flex-wrap:wrap}.tabs{margin-bottom:1.5rem}.tabs button[aria-pressed=true]{background:var(--accent-low);color:var(--accent-high)}.mono{font-family:var(--font-mono);font-size:.85em;overflow-wrap:anywhere}.confirm{margin-top:2rem;padding:1.2rem;border:1px solid var(--border);border-radius:6px;background:var(--surface)}.confirm h2{font-size:1.1rem}.confirm label{display:block;margin:1rem 0}</style>
